import React,{useEffect,useRef,useState} from 'react'; import './About.css'; import profileImg from '../Assets/aboutUs.jpg'; import { FiArrowUpRight } from 'react-icons/fi';
const About=()=>{const ref=useRef(null);const [visible,setVisible]=useState(false);useEffect(()=>{const observer=new IntersectionObserver(([entry])=>{if(entry.isIntersecting){setVisible(true);observer.disconnect()}},{threshold:.16});if(ref.current)observer.observe(ref.current);return()=>observer.disconnect()},[]);return <section className={`about-section ${visible?'is-visible':''}`} id="about" ref={ref}><div className="about-wrapper"><div className="about-image-wrap"><div className="about-orb"/><img src={profileImg} alt="BuildWebCanada team collaborating" className="about-img"/><div className="about-image-label"><span>01</span> Vancouver · Worldwide</div></div><div className="about-content"><p className="section-kicker">About BuildWebCanada</p><h2>Built by people<br/>who <span>care about</span><br/>the outcome.</h2><p className="about-description">We’re a small, senior collective of strategists, designers, and engineers. We bring clarity to complex ideas and turn them into digital products people genuinely enjoy using.</p><div className="about-points"><span>Strategy-led</span><span>Design-obsessed</span><span>Built to scale</span></div><a href="#contact" className="about-cta">Let’s work together <FiArrowUpRight/></a></div></div></section>};
export default About;
